use std::collections::BTreeMap;
use std::io::{self, Write};

use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;

/// Return the invoiceable seconds for an entry.
///
/// This is deliberately based on the stored duration: running entries have no
/// invoiceable duration and must never be included in an invoice.
fn invoiceable_seconds(entry: &TimeEntry) -> Option<i64> {
    (entry.billable && entry.stop.is_some()).then_some(entry.duration)
}

fn monthly_totals(entries: impl IntoIterator<Item = TimeEntry>) -> BTreeMap<String, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        if let Some(seconds) = invoiceable_seconds(&entry) {
            let month = entry.start.format("%Y-%m").to_string();
            *totals.entry(month).or_insert(0) += seconds;
        }
    }
    totals
}

pub struct InvoiceMonthlyCommand;

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let totals = monthly_totals(entries);
        let stdout = io::stdout();
        let mut output = stdout.lock();

        if totals.is_empty() {
            writeln!(output, "(no data)").expect("failed to print");
            return Ok(());
        }

        let total: i64 = totals.values().sum();
        for (month, seconds) in totals {
            writeln!(output, "{month}  {seconds}s").expect("failed to print");
        }
        writeln!(output, "Total  {total}s").expect("failed to print");
        Ok(())
    }
}

