                "2026-01-31T23:30:00Z",
                10,
                true,
                Some("2026-02-01T00:00:00Z"),
            ),
            entry(
                2,
                "2026-02-01T00:30:00Z",
                20,
                true,
                Some("2026-02-01T01:00:00Z"),
            ),
            entry(
                3,
                "2026-02-01T02:00:00Z",
                30,
                false,
                Some("2026-02-01T03:00:00Z"),
