            entry(4, "2026-02-01T04:00:00Z", 40, true, None),
        ]);

        assert_eq!(totals.get("2026-01"), Some(&10));
        assert_eq!(totals.get("2026-02"), Some(&20));
        assert_eq!(totals.len(), 2);
    }

    #[test]
    fn empty_totals_have_no_months() {
        assert!(monthly_totals(Vec::<TimeEntry>::new()).is_empty());
